/*
 * Account settings prototype — Tidepool design tokens.
 * Values come from the Figma "Theme" (Light/Dark) and "Sizing" collections.
 */

:root {
  /* Theme: Light */
  --surface-page: #ffffff;
  --text-primary: #1b2433;
  --button-background: #1f5fd6;
  --button-background-hover: #1849a8;
  --button-text: #ffffff;
  --field-border: #7d8799;

  /* Sizing */
  --gap-s: 4px;
  --padding-xs: 4px;
  --padding-s: 8px;
  --padding-m: 12px;
  --radii-button: 8px;
  --radii-field: 6px;
  --stroke-default: 1px;
}

/* Theme: Dark */
@media (prefers-color-scheme: dark) {
  :root {
    --surface-page: #10151f;
    --text-primary: #eef2f8;
    --button-background: #5b8def;
    --button-background-hover: #7aa3f2;
    --button-text: #0b1020;
    --field-border: #8f99ab;
  }
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--surface-page);
  color: var(--text-primary);
  font-family: Inter, system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 14px;
  line-height: 20px;
  font-weight: 500;
}

/* Frame: padding-m, column, gap-m */
.settings {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--padding-m);
  padding: var(--padding-m);
  min-height: 100vh;
}

/* Heading uses the design's "m" text style (Inter Medium 14/20). */
.settings__heading {
  margin: 0;
  font: inherit;
  font-size: 14px;
  line-height: 20px;
  font-weight: 500;
}

.settings__form {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--padding-m);
}

.settings__label {
  display: block;
  margin-bottom: var(--gap-s);
}

/* Field: 200 x 36, 1px field border, 6px radius, 8px padding */
.field {
  display: block;
  width: 200px;
  height: 36px;
  padding: var(--padding-s);
  font: inherit;
  font-size: 14px;
  line-height: 20px;
  font-weight: 500;
  color: var(--text-primary);
  background: var(--surface-page);
  border: var(--stroke-default) solid var(--field-border);
  border-radius: var(--radii-field);
}

.field:focus-visible {
  outline: 2px solid var(--button-background);
  outline-offset: 2px;
}

/* Button: 80 x 32, padding 4 / 12, 8px radius, Inter Medium 14/20 */
.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--gap-s);
  width: 80px;
  height: 32px;
  padding: var(--padding-xs) var(--padding-m);
  font: inherit;
  font-size: 14px;
  line-height: 20px;
  font-weight: 500;
  white-space: nowrap;
  color: var(--button-text);
  background: var(--button-background);
  border: 0;
  border-radius: var(--radii-button);
  cursor: pointer;
}

.button:hover:not(:disabled) {
  background: var(--button-background-hover);
}

.button:disabled {
  opacity: 0.5;
  cursor: default;
}

.button:focus-visible {
  outline: 2px solid var(--button-background);
  outline-offset: 2px;
}

/* Confirmation message: plain text, shown after a successful save. */
.settings__status {
  margin: 0;
  font-size: 14px;
  line-height: 20px;
  font-weight: 500;
  color: var(--text-primary);
}

.settings__status[hidden] {
  display: none;
}

