/*
 * Sign-in page styles. Uses only tokens from tokens.css.
 *
 * Not in the design system (assumed, confirm with design):
 *   - heading size/line-height (--heading-size, --heading-line-height)
 *   - focus ring colour (reuses the button background)
 *   - label/field spacing
 */

:root {
  --heading-size: 24px;
  --heading-line-height: 32px;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  background: var(--surface-page);
  color: var(--text-primary);
  font-family: var(--font-family);
  font-weight: var(--font-weight-medium);
  font-size: var(--font-size-m);
  line-height: var(--line-height-m);
  -webkit-font-smoothing: antialiased;
}

.page {
  display: flex;
  min-height: 100vh;
  align-items: center;
  justify-content: center;
  padding: 24px;
}

.sign-in {
  display: flex;
  flex-direction: column;
  gap: 16px;
  width: 320px;
  max-width: 100%;
}

.sign-in__heading {
  margin: 0 0 8px;
  font-family: inherit;
  font-weight: var(--font-weight-medium);
  font-size: var(--heading-size);
  line-height: var(--heading-line-height);
  color: var(--text-primary);
}

.field-group {
  display: flex;
  flex-direction: column;
  gap: var(--gap-s);
}

.field-label {
  color: var(--text-primary);
}

.field {
  width: 100%;
  height: 36px;
  padding: var(--padding-s);
  border: var(--stroke-default) solid var(--field-border);
  border-radius: var(--radii-field);
  background: var(--surface-page);
  color: var(--text-primary);
  font: inherit;
  font-weight: var(--font-weight-medium);
  font-size: var(--font-size-m);
  line-height: var(--line-height-m);
}

.field::placeholder {
  color: var(--field-border);
  opacity: 1;
}

.field:focus-visible,
.button:focus-visible {
  outline: 2px solid var(--button-background);
  outline-offset: 2px;
}

.button {
  width: 100%;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--gap-s);
  padding: var(--padding-xs) var(--padding-m);
  border: 0;
  border-radius: var(--radii-button);
  background: var(--button-background);
  color: var(--button-text);
  font: inherit;
  font-weight: var(--font-weight-medium);
  font-size: var(--font-size-m);
  line-height: var(--line-height-m);
  white-space: nowrap;
  cursor: pointer;
}

.button:hover {
  background: var(--button-background-hover);
}

