files.signup-prototype/components.css:
/* Tidepool components for the sign-up prototype. Requires tokens.css. */

body {
  margin: 0;
  padding: var(--padding-m);
  background: var(--surface-page-color);
  color: var(--text-primary-color);
  font-family: Inter, system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 14px;
  font-weight: 500;
  line-height: 20px;
}

/* Layout: page keeps padding/m from its edge and padding/m between its parts. */
.ds-stack {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--padding-m);
  margin: 0;
  padding: 0;
  border: 0;
}

/* Page heading: text style m. */
.ds-heading {
  margin: 0;
  font: inherit;
}

/* Field (Figma: field, 200 x 36). Typing only. */
.ds-field-label {
  display: flex;
  flex-direction: column;
  gap: var(--gap-s);
  font: inherit;
}

.ds-field {
  box-sizing: border-box;
  width: 200px;
  height: 36px;
  padding: var(--padding-s);
  border: var(--stroke-default) solid var(--field-border-color);
  border-radius: var(--radii-field);
  background: transparent;
  color: var(--text-primary-color);
  font: inherit;
}

.ds-field:user-invalid {
  border-color: var(--field-border-error-color);
}

/* Button (Figma: button, 80 x 32). One per screen, for the main action. */
.ds-button {
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--gap-s);
  width: 80px;
  height: 32px;
  padding: var(--padding-xs) var(--padding-m);
  border: 0;
  border-radius: var(--radii-button);
  background: var(--button-background-color);
  color: var(--button-text-color);
  font: inherit;
  white-space: nowrap;
  text-decoration: none;
  cursor: pointer;
}

.ds-button:hover {
  background: var(--button-background-hover-color);
}

/* Not in the Figma file; needed so keyboard focus is visible. */
.ds-button:focus-visible,
.ds-field:focus-visible,
.ds-option:focus-within {
  outline: 2px solid var(--button-background-color);
  outline-offset: 2px;
}

/* Tag (Figma: tag, Tone=Neutral). A status that does not change. */
.ds-tag {
  display: inline-flex;
  align-items: center;
  height: 20px;
  padding: var(--padding-xs) var(--padding-s);
  border-radius: var(--radii-chip);
  background: var(--chip-background-color);
  color: var(--chip-text-color);
  font-size: 12px;
  font-weight: 500;
  line-height: 16px;
}

/* Plan choice. The Figma file has no selection component, so this uses native
   radio inputs inside field-styled boxes. */
.ds-options {
  display: flex;
  flex-direction: column;
  gap: var(--gap-s);
  margin: 0;
  padding: 0;
  border: 0;
  min-width: 0;
}

.ds-legend {
  padding: 0;
  margin-bottom: var(--gap-s);
  font: inherit;
}

.ds-option {
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: var(--padding-s);
  width: 200px;
  padding: var(--padding-s);
  border: var(--stroke-default) solid var(--field-border-color);
  border-radius: var(--radii-field);
  cursor: pointer;
}

.ds-option:has(input:checked) {
  border-color: var(--button-background-color);
}

.ds-option input {
  margin: 0;
  accent-color: var(--button-background-color);
}

